  "source": "namespace Contribution\n\nopen B_fe98bbfbfb97628232bb09c5964d9ee6fa045bd4f96501a460ab0583772ba5a2.Contribution\nopen B_4f4126122d0700524796c405e145badf09c1ce0f46ce2280744811f1b2bad118.Contribution\n\nvariable {G : Type} [Group G] {d L : ℕ}\n\ntheorem plaq_triv {p a r b : G} (hp : p = 1) (hr : r = 1) (h : p * a * r⁻¹ * b⁻¹ = 1) :\n    a = b := by\n  rw [hp, hr, one_mul, inv_one, mul_one] at h\n  exact mul_inv_eq_one.mp h\n\ntheorem plaq_comm {p a r b : G} (h : p * a * r⁻¹ * b⁻¹ = 1) : p * a = b * r := by\n  rw [mul_inv_eq_one, mul_inv_eq_iff_eq_mul] at h\n  exact h\n\ntheorem shift_coord' (x : Site d L) {τ μ : Fin d} (h : μ ≠ τ) :\n    (x + e μ : Site d L) τ = x τ := by\n  rw [Pi.add_apply, e_ne (Ne.symm h), add_zero]\n\ntheorem sliceBase_shift (x : Site d L) {τ μ : Fin d} (h : μ ≠ τ) :\n    sliceBase (x + e μ) τ = sliceBase x τ + e μ := by\n  funext ν\n  by_cases hν : ν = τ\n  · rw [hν, Pi.add_apply, sliceBase, sliceBase, Function.update_self, Function.update_self,\n      e_ne (Ne.symm h), add_zero]\n  · rw [Pi.add_apply, sliceBase, sliceBase, Function.update_of_ne hν, Function.update_of_ne hν,\n      Pi.add_apply]\n\ntheorem last_wrap [NeZero L] (x : Site d L) (τ : Fin d) (hx : (x τ).val + 1 = L) :\n    x + e τ = sliceBase x τ := by\n  funext ν\n  by_cases hν : ν = τ\n  · rw [hν, sliceBase, Function.update_self]\n    exact (ZMod.val_eq_zero _).mp (val_add_e_of_last x τ hx)\n  · rw [Pi.add_apply, e_ne hν, add_zero, sliceBase, Function.update_of_ne hν]\n\ntheorem line_val [NeZero L] (b : Site d L) (τ : Fin d) (hb : b τ = 0) {k : ℕ} (hk : k < L) :\n    ((b + k • e τ : Site d L) τ).val = k := by\n  rw [Pi.add_apply, Pi.smul_apply, e_self, hb, zero_add, nsmul_eq_mul, mul_one,\n    ZMod.val_natCast, Nat.mod_eq_of_lt hk]\n\ntheorem sliceBase_coord (x : Site d L) (τ : Fin d) : sliceBase x τ τ = 0 :=\n  Function.update_self _ _ _\n\n/-- Along a `τ`-line, links that are invariant under one `τ`-step are constant. -/\ntheorem static_line [NeZero L] (V : LinkConfig G d L) (τ μ : Fin d) (b : Site d L)\n    (hb : b τ = 0)\n    (hstep : ∀ y : Site d L, (y τ).val + 1 < L → V (y + e τ) μ = V y μ) :\n    ∀ k, k < L → V (b + k • e τ) μ = V b μ\n  | 0, _ => by rw [zero_smul, add_zero]\n  | k + 1, hk => by\n    rw [← shift_succ' b τ k, hstep _ (by rw [line_val b τ hb (Nat.lt_of_succ_lt hk)]; exact hk),\n      static_line V τ μ b hb hstep k (Nat.lt_of_succ_lt hk)]\nwhere\n  shift_succ' (b : Site d L) (τ : Fin d) (k : ℕ) : b + k • e τ + e τ = b + (k + 1) • e τ :=\n    (add_assoc _ _ _).trans (congrArg (b + ·) (succ_nsmul _ k).symm)\n\n/-- Classical vacua of lattice Yang–Mills reduce to static data. For a faithful unitary\nrepresentation `ρ` (pr-10), a configuration with vanishing Wilson action is gauge equivalent\n(via the axial gauge of pr-12) to a flat configuration `V` whose `τ`-links are trivial off the\nlast slice, whose other links are independent of the `τ`-coordinate, and whose last-slice\nlinks — the Polyakov loops `P` — obey the parallel-transport relation\n`P(b) V(b, μ) = V(x, μ) P(b + e_μ)` with `b` the base point of `x`. -/\ntheorem result :\n    ∀ (G : Type) [Group G] (n d L : ℕ) [NeZero L] (τ : Fin d)\n      (ρ : G → Matrix (Fin n) (Fin n) ℂ), IsUnitaryRep ρ → Function.Injective ρ →\n      ∀ U : LinkConfig G d L, wilsonAction ρ U = 0 →\n        ∃ g : GaugeTransform G d L,\n          IsFlat (gaugeAct g U) ∧\n          (∀ x : Site d L, (x τ).val + 1 < L → gaugeAct g U x τ = 1) ∧\n          (∀ (x : Site d L) (μ : Fin d), μ ≠ τ →\n            gaugeAct g U x μ = gaugeAct g U (sliceBase x τ) μ) ∧\n          (∀ (x : Site d L) (μ : Fin d), μ ≠ τ → (x τ).val + 1 = L →\n            polyakovLoop U (sliceBase x τ) τ * gaugeAct g U (sliceBase x τ) μ =\n              gaugeAct g U x μ * polyakovLoop U (sliceBase x τ + e μ) τ) := by\n  intro G _ n d L _ τ ρ hρ hinj U hS\n  have hflat : IsFlat U :=\n    ((B_fe98bbfbfb97628232bb09c5964d9ee6fa045bd4f96501a460ab0583772ba5a2.Contribution.result).2.1\n      G n d L ρ hρ U).2.2.2 hinj |>.mp hS\n  obtain ⟨g, h1, h2, -⟩ :=\n    B_4f4126122d0700524796c405e145badf09c1ce0f46ce2280744811f1b2bad118.Contribution.result\n      G d L τ U\n  have hV : IsFlat (gaugeAct g U) := fun x μ ν => by\n    rw [plaquette_gaugeAct, hflat x μ ν, mul_one, mul_inv_cancel]\n  have hstep : ∀ μ : Fin d, μ ≠ τ → ∀ y : Site d L, (y τ).val + 1 < L →\n      gaugeAct g U (y + e τ) μ = gaugeAct g U y μ := fun μ hμ y hy =>\n    plaq_triv (h1 y hy) (h1 _ (by rw [shift_coord' y hμ]; exact hy)) (hV y τ μ)\n  refine ⟨g, hV, h1, fun x μ hμ => ?_, fun x μ hμ hx => ?_⟩\n  · have hk := static_line (gaugeAct g U) τ μ (sliceBase x τ) (sliceBase_coord x τ)\n      (hstep μ hμ) (x τ).val (ZMod.val_lt _)\n    rwa [sliceBase_add_val] at hk\n  · have hc := plaq_comm (hV x τ μ)\n    rw [h2 x hx, last_wrap x τ hx,\n      h2 _ (by rw [shift_coord' x hμ]; exact hx), sliceBase_shift x hμ] at hc\n    exact hc\n\nend Contribution\n",
